func TestNoFusionOutsideTriggeredImagePages(emonT *testing.T) {
	port.AssertEq(emonT, ofuse.OfActive(0, 1, 1), 0, "PDF and born digital never fuse")
	port.AssertEq(emonT, ofuse.OfActive(1, 0, 1), 0, "untriggered image never fuses")
	port.AssertEq(emonT, ofuse.OfActive(1, 1, 0), 0, "keyword gate is stacked")
	port.AssertEq(emonT, ofuse.OfActive(1, 1, 1), 1, "photo lane")
	port.AssertEq(emonT, ofuse.OfActive(1, 2, 1), 1, "thermal lane")
}

func TestValidNumericIncumbentIsProtected(emonT *testing.T) {
	port.AssertEq(emonT, ofuse.OfRule(1, 1, 1, 1, 1, 3, 0, 1000, 0), 4, "even unanimous perfect alternate cannot replace a valid number")
}

func TestNumericCandidatesMustBeFormatValid(emonT *testing.T) {
	port.AssertEq(emonT, ofuse.OfRule(1, 1, 0, 0, 1, 3, 0, 1000, 0), 4, "confidence and votes cannot admit malformed numbers")
}

func TestAlphaCandidatesNeedDictionaryOrAgreement(emonT *testing.T) {
	port.AssertEq(emonT, ofuse.OfRule(1, 0, 0, 0, 0, 1, 0, 1000, 0), 5, "unflagged high confidence is insufficient")
	port.AssertEq(emonT, ofuse.OfRule(1, 0, 0, 0, 1, 1, 0, 900, 600), 2, "dictionary permits exact margin")
	port.AssertEq(emonT, ofuse.OfRule(1, 0, 0, 0, 0, 2, 0, 500, 900), 1, "agreement can replace despite negative margin")
}

func TestAgreementMustBeatIncumbentVotes(emonT *testing.T) {
	port.AssertEq(emonT, ofuse.OfRule(1, 0, 0, 0, 0, 2, 2, 700, 700), 0, "vote tie keeps incumbent")
	port.AssertEq(emonT, ofuse.OfRule(1, 0, 0, 0, 0, 2, 1, 700, 700), 1, "strictly more agreeing readings")
}

func TestSingleReadingReplacementNeedsMargin300(emonT *testing.T) {
	port.AssertEq(emonT, ofuse.OfRule(1, 1, 0, 1, 0, 1, 0, 899, 600), 0, "299 keeps")
	port.AssertEq(emonT, ofuse.OfRule(1, 1, 0, 1, 0, 1, 0, 900, 600), 2, "300 replaces")
}

func TestInsertionNeedsConfidence700(emonT *testing.T) {
	port.AssertEq(emonT, ofuse.OfRule(0, 0, 0, 0, 0, 2, 0, 699, 0), 0, "agreement does not bypass insertion floor")
	port.AssertEq(emonT, ofuse.OfRule(0, 0, 0, 0, 0, 2, 0, 700, 0), 3, "700 inserts")
	port.AssertEq(emonT, ofuse.OfRule(0, 0, 0, 0, 1, 1, 0, 700, 0), 3, "dictionary permits single-reading alpha insertion")
	port.AssertEq(emonT, ofuse.OfRule(0, 1, 0, 1, 0, 1, 0, 700, 0), 3, "format permits single-reading numeric insertion")
}

func TestNoDeletionEvenWhenAllOtherReadingsAreNull(emonT *testing.T) {
	port.AssertEq(emonT, ofuse.OfRule(1, 0, 0, 0, 1, 0, 0, 1000, 0), 0, "zero candidate votes keeps the selected words")
}

func TestFusedCopyCannotInventCharacters(emonT *testing.T) {
	var words *port.Cells = port.NewCells()
	var source int32 = evidence.OwNew(words, 1, 10, 20, 110, 40, 10, 40, 110, 40, 0, 0, 123, 7, 2, 876, -1)
	var copied int32 = ofuse.OfCopy(words, source, 9, 8)
	port.AssertEq(emonT, evidence.OwGet(words, copied, evidence.HdTstart()), 123, "same recorded text span")
	port.AssertEq(emonT, evidence.OwGet(words, copied, evidence.HdTlen()), 7, "same recorded character count")
	port.AssertEq(emonT, evidence.OwGet(words, copied, evidence.HdConf()), 876, "same source confidence")
	port.AssertEq(emonT, evidence.OwGet(words, copied, evidence.HdX0()), 10, "same source box")
	port.AssertEq(emonT, evidence.OwGet(words, copied, ofuse.OfFrom()), source, "source row is explicit")
	port.AssertEq(emonT, evidence.OwGet(words, copied, evidence.OwfRun()), 9, "synthetic run")
	port.AssertEq(emonT, evidence.OwGet(words, copied, evidence.HdLine()), 8, "synthetic line")
	port.AssertEq(emonT, evidence.OwCount(words), 2, "original remains for D699")
	port.AssertEq(emonT, evidence.OwGet(words, source, evidence.HdLine()), 2, "source row remains unchanged")
}

func TestSlotsUseHalfOfTheSmallerBoxAndTransitiveLinks(emonT *testing.T) {
	var words *port.Cells = port.NewCells()
	var rows *port.Cells = port.NewCells()
	var parents *port.Cells = port.NewCells()
	var sorted *port.Cells = port.NewCells()
	evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1)
	evidence.OwNew(words, 1, 50, 0, 150, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1)
	evidence.OwNew(words, 1, 100, 0, 200, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1)
	evidence.OwNew(words, 1, 151, 0, 251, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1)
	port.CellsPush(rows, 0)
	port.CellsPush(rows, 1)
	port.CellsPush(rows, 2)
	port.CellsPush(rows, 3)
	ofuse.OfAlign(words, rows, parents, sorted)
	port.AssertEq(emonT, ofuse.OfRoot(parents, 0), ofuse.OfRoot(parents, 2), "half-overlap chain is one slot")
	port.AssertEq(emonT, ofuse.OfRoot(parents, 3), 3, "49 percent overlap stays separate")
}

func TestSlotsNeverLinkDifferentPages(emonT *testing.T) {
	var words *port.Cells = port.NewCells()
	var rows *port.Cells = port.NewCells()
	var parents *port.Cells = port.NewCells()
	var sorted *port.Cells = port.NewCells()
	evidence.OwNew(words, 1, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1)
	evidence.OwNew(words, 2, 0, 0, 100, 100, 0, 0, 0, 0, 0, 0, 0, 1, 0, 900, -1)
	port.CellsPush(rows, 0)
	port.CellsPush(rows, 1)
	ofuse.OfAlign(words, rows, parents, sorted)
	port.AssertEq(emonT, ofuse.OfRoot(parents, 0), 0, "page one")
	port.AssertEq(emonT, ofuse.OfRoot(parents, 1), 1, "page two")
}

