func TestFormatSpanBoundsDoNotOverflowOrReadOutsideRecordedText(emonT *testing.T) {
	var text *port.Cells = port.NewCells()
	port.CellsPush(text, 49)
	port.AssertEq(emonT, ofmt.OfmtValid(text, -1, 1), 0, "negative start")
	port.AssertEq(emonT, ofmt.OfmtValid(text, 0, 2), 0, "long span")
	port.AssertEq(emonT, ofmt.OfmtValid(text, 2147483647, 2147483647), 0, "hostile overflowing span")
	port.AssertEq(emonT, ofmt.OfmtValid(text, 0, 1), 1, "recorded digit")
}

